"""任务四预测方法网页：区分历史基线与最终集成模型。"""
from pathlib import Path
import csv
import json

ROOT=Path(__file__).resolve().parents[2]
TASK=ROOT/'交付文件'/'任务四_开放创作'
OUT=TASK/'02_2028洛杉矶预测'

def first(path):
    with path.open(encoding='utf-8-sig',newline='') as f:return next(csv.DictReader(f))

base=first(OUT/'模型回测摘要.csv')
advanced=first(TASK/'05_满分升级'/'升级模型验证摘要.csv')
params=json.loads((OUT/'模型参数与来源.json').read_text(encoding='utf-8'))
base_mae=float(base['backtest_mae_all_nocs'])
top_mae=float(base['backtest_mae_actual_ge5'])
project_mae=float(advanced['项目级2024回测MAE'])
host_rate=float(advanced['合成对照主场效应中位数'])
html='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>预测方法与验证｜洛杉矶2028</title><style>
:root{--paper:#f4f0e7;--ink:#142d34;--teal:#207a84;--gold:#bd8133;--line:#d7dedb}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:"Microsoft YaHei",sans-serif}.m-hero{padding:10vh 7vw 8vh;min-height:68vh;background:linear-gradient(135deg,#102e36,#1d5360);color:#f0f6f2}.m-eyebrow{color:#e4b375;font-size:13px;font-weight:900;letter-spacing:.14em}.m-hero h1{font-size:clamp(58px,8vw,112px);line-height:1.04;margin:24px 0}.m-lead{font-size:clamp(18px,2vw,24px);line-height:1.75;max-width:900px;color:#d2e5e0}.m-wrap{max-width:1260px;margin:auto;padding:0 6vw 80px}.m-section{padding:65px 0;border-top:1px solid var(--line)}.m-section h2{font-size:clamp(32px,4.5vw,56px);margin:8px 0 22px}.m-section p{line-height:1.82;max-width:930px}.m-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.m-kpis article{background:#fff9;border:1px solid var(--line);border-radius:18px;padding:24px}.m-kpis strong{display:block;color:var(--teal);font-size:clamp(31px,4vw,51px)}.m-kpis span{font-size:13px}.m-tabs{display:flex;gap:9px;flex-wrap:wrap;margin:25px 0 16px}.m-tabs button{border:1px solid var(--line);border-radius:99px;background:#fff;padding:12px 21px;cursor:pointer;font-weight:800}.m-tabs button[aria-selected=true]{background:var(--ink);color:#fff}.m-panel{display:grid;grid-template-columns:.7fr 1.3fr;gap:30px;background:#fff9;border:1px solid var(--line);border-radius:22px;padding:32px}.m-panel h3{font-size:clamp(27px,3vw,42px);margin:0 0 12px}.m-panel .m-tag{font-size:12px;color:var(--gold);font-weight:900}.m-panel ul{margin:0;padding-left:21px;line-height:1.9}.m-panel li{margin:0 0 9px}.m-note{padding:23px 27px;background:#e7eee9;border-left:4px solid var(--teal);line-height:1.8;margin-top:20px}.m-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.m-grid article{padding:25px;background:#fff9;border:1px solid var(--line);border-radius:16px}.m-grid h3{margin:0 0 10px}.m-figures{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.m-figures img{width:100%;border-radius:14px;border:1px solid var(--line)}.m-links{display:flex;gap:10px;flex-wrap:wrap;margin-top:24px}.m-links a{padding:11px 15px;border:1px solid var(--line);border-radius:10px;background:#fff;text-decoration:none}.m-small{font-size:13px;color:#627478}.m-formula{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:20px 0}.m-formula div{padding:22px;border-radius:14px;background:#123b44;color:#f1f7f3}.m-formula b{display:block;color:#9ae1d3;font-size:36px}.m-formula small{font-size:13px}@media(max-width:800px){.m-kpis{grid-template-columns:repeat(2,1fr)}.m-panel,.m-grid,.m-figures{grid-template-columns:1fr}.m-wrap{padding:0 20px 50px}.m-hero{padding:110px 24px 55px}.m-formula{grid-template-columns:1fr}}
</style></head><body><header class="m-hero"><div class="m-eyebrow">任务四 / 方法与复现</div><h1>预测不是答案，<br>是可检验的假设</h1><p class="m-lead">洛杉矶2028预测包含一套透明历史基线和一套项目级集成模型。两者使用不同输入和验证尺度，必须分别阅读。</p></header><main class="m-wrap"><section class="m-section"><span class="m-eyebrow">读数指南</span><h2>先分清两套模型</h2><div class="m-kpis"><article><strong>353</strong><span>预计奖牌小项</span></article><article><strong>__BASE_MAE__</strong><span>历史基线回测MAE，代表团总奖牌单位</span></article><article><strong>__PROJECT_MAE__</strong><span>项目级留出回测MAE，运动员行代理单位</span></article><article><strong>45/45/10</strong><span>最终集成权重，百分比</span></article></div><p class="m-small">两个 MAE 的观察单位不同，不能直接比较大小。预测榜中的不确定性区间来自历史基线回测残差，不应直接当作集成模型的校准区间。</p></section><section class="m-section" id="模型"><span class="m-eyebrow">模型选择</span><h2>切换方法，核对假设</h2><div class="m-tabs" role="tablist" aria-label="预测方法"><button type="button" role="tab" data-model="baseline" aria-selected="true">历史基线</button><button type="button" role="tab" data-model="ensemble" aria-selected="false">项目级集成</button></div><div class="m-panel"><div><div class="m-tag" id="m-tag"></div><h3 id="m-title"></h3><p id="m-summary"></p></div><ul id="m-steps"></ul></div><div class="m-note" id="m-boundary"></div></section><section class="m-section" id="验证"><span class="m-eyebrow">历史验证</span><h2>数字要接受回测</h2><div class="m-grid"><article><h3>基线：跨届总量回测</h3><p>使用2012、2016、2024历史回测残差。全体代表团平均绝对误差 <b>__BASE_MAE__ 枚</b>；实际不少于5枚的代表团为 <b>__TOP_MAE__ 枚</b>。残差的10%和90%分位形成基线的80%区间。</p></article><article><h3>集成：2024项目级留出</h3><p>2024届不参加项目级模型训练，以代表团×体育大类为单位，留出回测MAE为 <b>__PROJECT_MAE__ 行</b>。这反映项目结构预测误差，不等同于官方小项奖牌误差。</p></article></div><div class="m-figures"><img src="核心图表/历史回测散点.png" alt="历史基线回测散点图"><img src="核心图表/LA2028预测总览.png" alt="洛杉矶2028预测总览图"></div></section><section class="m-section"><span class="m-eyebrow">最终集成</span><h2>让每一项增量都有出处</h2><div class="m-formula"><div><b>45%</b><small>透明历史基线</small></div><div><b>45%</b><small>项目级随机森林与梯度提升</small></div><div><b>10%</b><small>新增运动排名信号</small></div></div><p>项目级输入包括前两届表现、趋势、代表团整体强度和项目竞争规模。新增运动使用五项单项组织的排名或竞技代理快照。主场项以赛前两届走势匹配非主办代表团，构造加权合成对照；历史效应中位数为 <b>__HOST_PCT__%</b>，模型采用其55%作为收缩后的情景调整。</p><div class="m-note">主办权并非随机。合成对照提供有条件的反事实参考，不能证明严格因果效应。2028资格、伤病、名单和项目格局仍会改变实际结果。</div></section><section class="m-section"><span class="m-eyebrow">赛后验证协议</span><h2>2028之后如何判分</h2><div class="m-grid"><article><h3>数量与排序</h3><p>分别计算总奖牌和项目级的MAE、RMSE，检验斯皮尔曼等级相关与前十命中率。</p></article><article><h3>区间与机制</h3><p>检查80%区间覆盖率；拆分新增项目、主场和历史趋势的实际贡献，对比事前假设。</p></article></div><div class="m-links"><a href="LA2028奖牌预测完整榜.csv">下载历史基线预测 ↓</a><a href="LA2028机器学习集成预测榜.csv">下载集成预测 ↓</a><a href="../05_满分升级/新增项目权威排名特征.csv">下载新增运动排名信号 ↓</a><a href="../05_满分升级/主场效应合成对照.csv">下载主场合成对照 ↓</a><a href="预测方法与验证方案.md">查看 Markdown 底稿 ↗</a></div><p class="m-small">原始数据、代码与完整自动验收随交付包提供。官方项目数与新增运动依据见底稿列出的国际奥委会来源。</p></section></main><script>const content={baseline:{tag:'透明基线 / 代表团总量',title:'从最近三届出发',summary:'分别预测金、银、铜，再按2028奖牌小项规模调整。',steps:['最近三届权重依次为 0.2、0.3、0.5；最近两届差值的15%形成趋势项。','美国固定增加12枚总奖牌属于早期可关闭情景假设，不是最终集成模型的主场估计。','新增运动也以单独情景增量处理；历史回测残差用于构建基线80%区间。'],boundary:'适用范围：透明、易复现的总量参照。它展示假设敏感性，不使用项目级竞争格局。'},ensemble:{tag:'最终集成 / 项目级信息',title:'从总量走向项目结构',summary:'组合历史基线、项目级机器学习和五项新增运动排名信号。',steps:['项目级随机森林与梯度提升按60%/40%组合，2024届作为完全留出验证。','五项新增运动将单项组织排名或竞技代理转为归一化信号，保留快照与来源。','主场使用近邻加权合成对照估计，再仅采纳历史效应中位数的55%。'],boundary:'适用范围：最终展示的集成点估计。页面没有把历史基线的80%区间宣称为集成模型的独立校准区间。'}};function show(model){const x=content[model];document.querySelector('#m-tag').textContent=x.tag;document.querySelector('#m-title').textContent=x.title;document.querySelector('#m-summary').textContent=x.summary;document.querySelector('#m-steps').innerHTML=x.steps.map(t=>`<li>${t}</li>`).join('');document.querySelector('#m-boundary').textContent=x.boundary;document.querySelectorAll('.m-tabs button').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.model===model)))}document.querySelector('.m-tabs').onclick=e=>{let b=e.target.closest('button[data-model]');if(b)show(b.dataset.model)};show('baseline');</script></body></html>'''
html=html.replace('__BASE_MAE__',f'{base_mae:.2f}').replace('__TOP_MAE__',f'{top_mae:.2f}').replace('__PROJECT_MAE__',f'{project_mae:.2f}').replace('__HOST_PCT__',f'{host_rate*100:.1f}')
html=html.replace('</style>','body header.m-hero{background:linear-gradient(135deg,#102e36,#1d5360)!important;color:#f0f6f2!important}body header.m-hero .m-lead{color:#d2e5e0!important}body.xz-dark .m-panel,body.xz-dark .m-grid article,body.xz-dark .m-kpis article{background:#173740!important;color:#e9f4f1!important}body.xz-dark .m-note{background:#244c50!important;color:#e9f4f1!important}</style>',1)
html=html.replace('href="../05_满分升级/','href="../05_满分升级/')
(OUT/'index.html').write_text(html,encoding='utf-8')
print(OUT/'index.html')
